        require(pauseGuardians[msg.sender], DataServicePausableNotPauseGuardian(msg.sender));
        _;
    }

    /// @inheritdoc IDataServicePausable
    function pause() external override onlyPauseGuardian {
        _pause();
    }

    /// @inheritdoc IDataServicePausable
